export type User = {
  id: string;
  phone: string;
  name: string;
  role: "admin" | "customer";
  createdAt: number;
};
export type PriceTier = { minCartons: number; price: number };
export type Product = {
  id: string;
  slug: string;
  name: string;
  sku: string;
  category: string;
  description: string;
  price: number;
  compareAt: number;
  unit: string;
  minOrder: number;
  stock: number;
  image: string;
  images: string[];
  status: "published" | "draft";
  featured: boolean;
  createdAt: number;
  updatedAt: number;
  vendor: string;
  verified: boolean;
  specification: string;
  packSize: number;
  sizes: string[];
  tiers: PriceTier[];
  gstRate: number;
  dispatchDays: number;
  shipsFrom: string;
};
export type CartItem = {
  id: string;
  productId: string;
  name: string;
  image: string;
  vendor: string;
  verified: boolean;
  size: string;
  quantity: number;
  packSize: number;
  stock: number;
  minOrder: number;
  unitPrice: number;
  subtotal: number;
  tax: number;
  gstRate: number;
  saved: boolean;
  available: boolean;
};
export type Cart = {
  items: CartItem[];
  subtotal: number;
  tax: number;
  discount: number;
  shipping: number;
  total: number;
  cartons: number;
  coupon: string;
  shippingLabel: string;
  checkoutReady: boolean;
};
export type Address = {
  name: string;
  phone: string;
  line1: string;
  line2: string;
  city: string;
  state: string;
  pincode: string;
  gstin: string;
};
export type Order = {
  id: string;
  orderNumber: string;
  userId: string;
  phone: string;
  address: Address;
  items: CartItem[];
  subtotal: number;
  tax: number;
  discount: number;
  shipping: number;
  total: number;
  status: string;
  paymentStatus: string;
  createdAt: number;
};
